use crate::wasi::clocks::wall_clock;

struct Node;

/// Format a Unix timestamp (seconds since 1970-01-01 UTC) as `YYYY-MM-DD`,
/// using Howard Hinnant's `civil_from_days` algorithm. The year is clamped to
/// 0..=9999 so the result is always exactly 10 characters.
fn civil_date(unix_secs: u64) -> String {
    let z = (unix_secs / 86_400) as i64 + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    let y = y.clamp(0, 9999);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        let date = civil_date(started);
        RunInfo { date, started }
    }
}

export!(Node);
